      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "optional reference images (sandbox path, http(s) URL, or base64) for endpoints that accept image input"
    }
  },
  "required": [
    "prompt"
  ]
}

{
  "type": "object",
  "properties": {
    "model": {
      "type": "string",
      "description": "decision model slug, e.g. inception/mercury-decide:free"
    },
    "state": {
      "description": "the content the questions decide about: a string, or a JSON object/array of related context"
    },
    "questions": {
      "type": "object",
      "description": "typed questions keyed by name, e.g. {\"is_bug\": {\"type\": \"bool\", \"instructions\": \"Is this a defect?\", \"criteria\": {\"true\": \"...\", \"false\": \"...\"}}, \"team\": {\"type\": \"choice\", \"instructions\": \"Which team?\", \"criteria\": {\"frontend\": \"...\", \"payments\": \"...\"}}}"
    }
  },
  "required": [
    "model",
    "state",
    "questions"
  ]
}

{
  "type": "object",
  "properties": {
    "id": {
      "type": "string",
      "description": "Optional: a specific subagent id. Omit to list all."
    }
  }
}

{
  "type": "object",
  "properties": {
    "id": {
      "type": "string",
      "description": "The subagent id to observe."
    },
    "tail": {
      "type": "integer",
      "description": "Number of recent messages to read (default 10)."
    }
  },
  "required": [
    "id"
  ]
}

{
  "type": "object",
  "properties": {
    "id": {
      "type": "string",
      "description": "The subagent id to message."
    },
    "message": {
      "type": "string",
      "description": "The follow-up instruction or question."
    }
  },
  "required": [
    "id",
    "message"
  ]
}

{
  "type": "object",
  "properties": {
    "id": {
      "type": "string",
